    },
    totalItems() {
      return this.filteredItems.length;
    },
    pageCount() {
      return Math.ceil(this.totalItems / this.itemsPerPage);
    },
    visiblePages() {
      const pages = [];
      const start = Math.max(1, this.currentPage - 2);
      const end = Math.min(this.pageCount, this.currentPage + 2);
      for (let i = start; i <= end; i++) {
        pages.push(i);
      }
      return pages;
    },
    // Pagination for supplier transactions
    supplierPageCount() {
      return Math.ceil((this.supplierTransactions?.length || 0) / this.supplierItemsPerPage);
    },
    supplierVisiblePages() {
      const totalPages = this.supplierPageCount;
      const current = this.supplierCurrentPage;
      const delta = 2;
      let start = Math.max(1, current - delta);
      let end = Math.min(totalPages, current + delta);
      if (end - start < 4) {
        if (start === 1) {
          end = Math.min(totalPages, start + 4);
        } else {
          start = Math.max(1, end - 4);
        }
      }
      const pages = [];
      for (let i = start; i <= end; i++) {
        pages.push(i);
      }
      return pages;
    },
    // Paginated supplier transactions
    paginatedSupplierTransactions() {
      if (!this.supplierTransactions || this.supplierTransactions.length === 0) {
        return [];
